/**
 * vocabularyExpanded.js
 *
 * Expanded Arabic vocabulary dataset for Gogo Arabic.
 * Contains 500 A1, 1,000 A2, 2,000 B1, and 1,500 B2 words (5,000 total new entries).
 *
 * These words supplement vocabulary.json (~250 words) and vocabulary-final.json (~970 words).
 * vocabularyAll.js (updated in plan 46-03) merges all sources into the 5,000+ word target.
 *
 * Schema (VOCAB-06 compliant):
 * {
 *   id:              string   — unique ID, prefix "exp_a1_", "exp_a2_", "exp_b1_", or "exp_b2_"
 *   arabic:          string   — Arabic script with diacritics where standard
 *   english:         string   — English gloss
 *   transliteration: string   — Romanized Arabic, no diacritic marks
 *   root:            string|null — trilateral root (null for particles/pronouns/loanwords)
 *   category:        string   — semantic category
 *   cefrLevel:       "A1"|"A2"|"B1"|"B2"
 *   frequency:       number   — A1: 4000–9999; A2: 2000–3999; B1: 500–1999; B2: 1–499
 *   difficulty:      1|2|3|4  — 1 for A1, 2 for A2, 3 for B1, 4 for B2
 * }
 */

